blocks.text:
/* Factory Board v2 — style. Design tokens mirror site/index.html (the
   slate palette, JetBrains Mono, pill radii): the board is part of the
   same product. Customize ONLY the :root variables (and the
   data-theme="light" overrides) to restyle for your site. */

:root, :root[data-theme="dark"] {
  --bg: #020617;
  --panel: rgba(15, 23, 42, 0.5);
  --panel-solid: #0f172a;
  --panel-2: rgba(15, 23, 42, 0.22);
  --text: #ffffff;
  --muted: #94a3b8;
  --dim: #475569;
  --line: #1e293b;
  --line-2: #334155;
  --accent: #22d3ee;

  --ok: #34d399;
  --bad: #fb7185;
  --run: #fbbf24;

  /* pipeline stage colors (mini timeline dots) */
  --st-dev: #22d3ee;
  --st-pr: #94a3b8;
  --st-rev: #a78bfa;
  --st-app: #fbbf24;
  --st-val: #fb923c;
  --st-mrg: #34d399;

  --card-shadow: 0 1px 3px rgba(0, 0, 0, .5);
  --sk: rgba(148, 163, 184, .08);
}
:root[data-theme="light"] {
  --bg: #f8fafc;
  --panel: #ffffff;
  --panel-solid: #ffffff;
  --panel-2: rgba(248, 250, 252, .65);
  --text: #0f172a;
  --muted: #64748b;
  --dim: #94a3b8;
  --line: #e2e8f0;
  --line-2: #cbd5e1;
  --accent: #0891b2;

  --ok: #059669;
  --bad: #e11d48;
  --run: #d97706;

  --st-dev: #0891b2;
  --st-pr: #64748b;
  --st-rev: #7c3aed;
  --st-app: #d97706;
  --st-val: #ea580c;
  --st-mrg: #059669;

  --card-shadow: 0 1px 2px rgba(31, 35, 40, .08);
  --sk: rgba(100, 116, 139, .12);
}

* { box-sizing: border-box; }
html { scrollbar-color: var(--line-2) transparent; }
body {
  margin: 0; background: var(--bg); color: var(--text);
  font: 13px/1.5 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo,
    Consolas, 'Liberation Mono', monospace;
  -webkit-font-smoothing: antialiased;
}

/* ── topbar ─────────────────────────────────────────────────────── */
.topbar {
  display: flex; align-items: center; justify-content: space-between;
  padding: 12px 20px; border-bottom: 1px solid var(--line);
  background: var(--panel-solid);
  position: sticky; top: 0; z-index: 20;
}
.brand { display: flex; align-items: center; gap: 10px; }
.logo { display: inline-flex; color: var(--accent); }
.brand h1 {
  font-size: 15px; margin: 0; font-weight: 700;
  letter-spacing: -0.025em; white-space: nowrap;
  overflow: hidden; text-overflow: ellipsis;
}
.live {
  width: 8px; height: 8px; border-radius: 50%; background: var(--ok);
  animation: pulse 2.4s infinite; flex: none;
}
@keyframes pulse { 0%, 100% { opacity: 1 } 50% { opacity: .35 } }
.topbar-right { display: flex; gap: 12px; align-items: center; color: var(--muted); }
.clock { font-size: 12px; font-variant-numeric: tabular-nums; }
.theme-btn {
  display: inline-flex; align-items: center; justify-content: center;
  background: none; border: 1px solid var(--line); color: var(--muted);
  border-radius: 8px; width: 30px; height: 26px; cursor: pointer;
}
.theme-btn:hover { color: var(--text); border-color: var(--line-2); }
:root[data-theme="dark"] .icon-sun { display: none; }
:root[data-theme="light"] .icon-moon { display: none; }

/* ── tabs ───────────────────────────────────────────────────────── */
.factory-tabs {
  display: flex; gap: 8px; padding: 12px 20px 0; flex-wrap: wrap;
  position: sticky; top: 51px; z-index: 19; background: var(--bg);
}
.tab {
  border: 1px solid var(--line); background: var(--panel-solid);
  color: var(--muted);
  padding: 6px 14px; border-radius: 999px; cursor: pointer;
  font: inherit; font-size: 12px; white-space: nowrap;
}
.tab:hover { color: var(--text); border-color: var(--line-2); }
.tab.on {
  color: var(--text); border-color: var(--accent);
  box-shadow: inset 0 0 0 1px var(--accent);
}

/* ── statusline ─────────────────────────────────────────────────── */
.statusline { display: flex; gap: 8px; padding: 12px 20px 0; flex-wrap: wrap; }
.pill {
  background: var(--panel-solid); border: 1px solid var(--line);
  color: var(--muted);
  border-radius: 999px; padding: 3px 10px; font-size: 11px;
}
.pill b { color: var(--run); font-weight: 700; }

/* ── lanes grid ─────────────────────────────────────────────────── */
.lanes {
  display: grid; gap: 12px; padding: 12px 20px 20px;
  grid-template-columns: repeat(6, minmax(250px, 1fr));
  grid-auto-flow: column;
  overflow-x: auto;                 /* horizontal scroll on narrow screens */
  align-items: start;
}
@media (min-width: 1600px) {
  .lanes { grid-template-columns: repeat(6, 1fr); grid-auto-flow: row; }
}
.lane {
  background: var(--panel); border: 1px solid var(--line);
  border-radius: 12px; min-width: 0;
  border-top: 2px solid var(--accent, var(--line-2));
}
.lane-head {
  display: flex; justify-content: space-between; align-items: center; gap: 8px;
  padding: 9px 12px; border-bottom: 1px solid var(--line);
  font-size: 10.5px; text-transform: uppercase; letter-spacing: .08em;
  color: var(--muted);
  position: sticky; top: 0;         /* stays visible while the lane scrolls */
  background: var(--panel-solid); border-radius: 12px 12px 0 0;
  z-index: 2;
}
.count {
  background: var(--panel-2); border: 1px solid var(--line);
  border-radius: 999px; padding: 0 8px; font-variant-numeric: tabular-nums;
}
.lane-body {
  padding: 8px; display: flex; flex-direction: column; gap: 8px;
  max-height: calc(100vh - 240px); overflow-y: auto;
}
.empty { color: var(--dim); text-align: center; padding: 18px 0; font-size: 12px; }

/* ── cards ──────────────────────────────────────────────────────── */
.card {
  display: block; background: var(--panel-solid); border: 1px solid var(--line);
  border-radius: 10px; padding: 9px 11px; color: var(--text);
  text-decoration: none; box-shadow: var(--card-shadow);
  transition: border-color .12s ease;
}
.card:hover { border-color: var(--accent); }
.card-top { display: flex; gap: 8px; align-items: baseline; min-width: 0; }
.pr { color: var(--accent); font-weight: 700; white-space: nowrap; }
.pos { color: var(--muted); font-size: 11px; }
.title {
  font-size: 12px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  flex: 1 1 auto; min-width: 0;
}
.age {
  color: var(--muted); font-size: 11px; white-space: nowrap; flex: none;
  border: 1px solid var(--line); border-radius: 999px; padding: 0 7px;
  font-variant-numeric: tabular-nums; cursor: help;
}
.labels { margin-top: 6px; display: flex; flex-wrap: wrap; gap: 4px; }
.lbl {
  font-size: 10px; color: var(--muted); border: 1px solid var(--line);
  border-radius: 999px; padding: 0 7px; max-width: 100%;
  overflow: hidden; text-overflow: ellipsis;
}
.lbl.hot {
  color: var(--text); border-color: var(--st-rev);
  background: color-mix(in srgb, var(--st-rev) 10%, transparent);
}
.meta {
  margin-top: 6px; display: flex; gap: 10px; align-items: center;
  color: var(--muted); font-size: 11px; flex-wrap: wrap;
}
.checks { display: flex; gap: 6px; align-items: center; }
.dot { width: 8px; height: 8px; border-radius: 50%; display: inline-block; flex: none; }
.dot.ok { background: var(--ok); }
.dot.bad { background: var(--bad); }
.dot.run { background: var(--run); animation: pulse 1.6s infinite; }

/* ── mini timeline (SVG) ────────────────────────────────────────── */
.tl { display: block; width: 100%; height: 14px; margin-top: 8px; }
.tl-axis { stroke: var(--line-2); stroke-width: 1.5; }
.tl circle { fill: var(--st-pr); }
.tl circle:hover { stroke: var(--text); stroke-width: 1; }
.tl .st-dev  { fill: var(--st-dev); }
.tl .st-rev  { fill: var(--st-rev); }
.tl .st-app  { fill: var(--st-app); }
.tl .st-val  { fill: var(--st-val); }
.tl .st-mrg  { fill: var(--st-mrg); }
.tl .first   { stroke: var(--line-2); stroke-width: 1.5; }
.tl .last    { stroke: var(--text); stroke-width: 1; }

/* ── v3 lane summary + progress bar ─────────────────────────────── */
.lane-sum {
  padding: 6px 12px 0; color: var(--muted); font-size: 10.5px;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.lane-sum b { color: var(--text); font-size: 11.5px; }
.lane-sum .s-done { color: var(--ok); }
.lane-sum .s-inflight { color: var(--accent); }
.lane-sum .s-queued { color: var(--muted); }
.lane-sum .s-blocked { color: var(--bad); }
.lane-bar {
  display: flex; gap: 2px; height: 3px; margin: 6px 12px 0;
  border-radius: 2px; overflow: hidden;
}
.lane-bar .seg { display: block; min-width: 4px; }
