        ? '<circle class="' + pts[0].cls + ' first last" cx="50" cy="5" r="3">' +
          '<title>' + esc(pts[0].name) + ' · ' + esc(clockTime(pts[0].raw)) +
          ' (' + esc(ago(pts[0].raw)) + ')</title></circle>'
        : '') +
