{"newText":"  // ── cards ──────────────────────────────────────────────────────────────────","oldText":"  // ── mini timeline (SVG): transition dots on a proportional axis ────────────
  function timelineSvg(c) {
    var pts = STAGES.filter(function (s) { return c[s.k]; })
      .map(function (s) {
        return { t: new Date(c[s.k]).getTime(), cls: s.cls,
                 name: s.name, raw: c[s.k] };
      })
      .filter(function (p) { return !isNaN(p.t); })
      .sort(function (a, b) { return a.t - b.t; });
    if (pts.length < 1) return '';
    var min = pts[0].t, max = pts[pts.length - 1].t;
    var span = Math.max(max - min, 1);
    var dots = pts.map(function (p, i) {
      var x = pts.length === 1 ? 50 : 3 + (94 * (p.t - min) / span);
      var first = i === 0, last = i === pts.length - 1;
      return '<circle class="' + p.cls + (first ? ' first' : '') +
             (last ? ' last' : '') + '" cx="' + x.toFixed(1) +
             '" cy="5" r="' + (first || last ? 3 : 2.5) + '">' +
             '<title>' + esc(p.name) + ' · ' + esc(clockTime(p.raw)) +
             ' (' + esc(ago(p.raw)) + ')</title></circle>';
    }).join('');
    return '<svg class="tl" viewBox="0 0 100 10" preserveAspectRatio="none" ' +
      'role="img" aria-label="pipeline timeline">' +
      '<line class="tl-axis" x1="3" y1="5" x2="97" y2="5"></line>' +
      (pts.length === 1 ? '' : dots) +
      (pts.length === 1
        ? '<circle class="' + pts[0].cls + ' first last" cx="50" cy="5" r="3">' +
          '<title>' + esc(pts[0].name) + ' · ' + esc(clockTime(pts[0].raw)) +
          ' (' + esc(ago(pts[0].raw)) + ')</title></circle>'
        : '') +
      '</svg>';
  }

  // ── cards ──────────────────────────────────────────────────────────────────","path":"site/factory/app.js"}

{"newText":"/* ── lanes strip (gh-726) ───────────────────────────────────────── */
/* ONE horizontal strip, always: fixed compact lane width + horizontal
   scroll as the overflow strategy — never a wrapped lone lane, whatever
   the lane count or viewport (--lane-w is the deploy knob). */
.lanes {
  display: flex; gap: 12px; padding: 12px 20px 20px;
  overflow-x: auto; align-items: flex-start;
}
.lane {
  background: var(--panel); border: 1px solid var(--line);
  border-radius: 12px; flex: 0 0 var(--lane-w, 290px);
  border-top: 2px solid var(--accent, var(--line-2));
}","oldText":"/* ── lanes grid ─────────────────────────────────────────────────── */
.lanes {
  display: grid; gap: 12px; padding: 12px 20px 20px;
  grid-template-columns: repeat(6, minmax(250px, 1fr));
  grid-auto-flow: column;
  overflow-x: auto;                 /* horizontal scroll on narrow screens */
  align-items: start;
}
@media (min-width: 1600px) {
  .lanes { grid-template-columns: repeat(6, 1fr); grid-auto-flow: row; }
}
.lane {
  background: var(--panel); border: 1px solid var(--line);
  border-radius: 12px; min-width: 0;
  border-top: 2px solid var(--accent, var(--line-2));
}","path":"site/factory/styles.css"}

{"newText":"/* ── labeled stepper (gh-726): named stages, colored by state ───── */
.stepper { display: flex; margin-top: 8px; }
.step {
  flex: 1; min-width: 0; position: relative;
  display: flex; flex-direction: column; align-items: center; gap: 3px;
}
/* connector: from the previous node's center to this one */
.step::before {
  content: ''; position: absolute; top: 4px; left: -50%; width: 50%;
  height: 2px; background: var(--line-2);
}
.step:first-child::before { display: none; }
.step-dot {
  width: 8px; height: 8px; border-radius: 50%; flex: none;
  background: var(--line-2);
}
.step-name {
  font-size: 8.5px; line-height: 1; letter-spacing: .02em;
  color: var(--dim); max-width: 100%;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
/* done — solid; the connector behind a done node reads as progress */
.step.st-done::before { background: var(--ok); }
.step.st-done .step-dot { background: var(--ok); }
.step.st-done .step-name { color: var(--muted); }
/* current — highlighted, pulsing */
.step.st-current .step-dot {
  background: var(--accent); animation: pulse 1.6s infinite;
}
.step.st-current .step-name { color: var(--text); font-weight: 700; }
/* pending — dim outline, no fill */
.step.st-pending .step-dot {
  background: transparent; border: 1.5px solid var(--dim);
}
/* failed — red, unmissable */
.step.st-failed .step-dot { background: var(--bad); }
.step.st-failed .step-name { color: var(--bad); font-weight: 700; }","oldText":"/* ── mini timeline (SVG) ────────────────────────────────────────── */
.tl { display: block; width: 100%; height: 14px; margin-top: 8px; }
