  function fmtDur(ms) {
    if (ms == null || isNaN(ms) || ms < 0) return '';
    var s = Math.round(ms / 1000);
    if (s < 60) return s + 's';
    var m = Math.floor(s / 60);
    if (m < 60) return m + 'm';
    var h = Math.floor(m / 60);
    var hm = m % 60;
    if (h < 24) return hm ? h + 'h' + hm + 'm' : h + 'h';
    var d = Math.floor(h / 24);
    var hh = h % 24;
    return hh ? d + 'd' + hh + 'h' : d + 'd';
